function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
function view(v){if(!['home','sell','market','requests','staff'].includes(v))throw Error('Unknown view');$$('.view').forEach(e=>e.hidden=e.id!==v+'-view');$$('.nav').forEach(e=>e.classList.toggle('active',e.dataset.view===v||(v==='sell'&&e.dataset.view==='home')));if(v==='requests'||v==='staff')renderRequests();window.scrollTo({top:0,behavior:'instant'});return v}
$$('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$$('.brand').forEach(a=>a.onclick=e=>{e.preventDefault();view('home')});
function openInfo(title,html){$('#info-content').innerHTML=`<p class="eyebrow">MEDICYCLE DEMO</p><h2>${esc(title)}</h2>${html}`;$('#info-dialog').showModal()}
$$('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
function selectSpotlight(index){if(!Number.isInteger(index)||!devices[index])throw Error('Unknown device');activeDevice=index;const d=devices[index];$('#spotlight-image').src='assets/'+d.img;$('#spotlight-image').alt='Exploded 3D concept illustration of '+d.name;$('#spotlight-number').textContent=`0${index+1} / 04`;$('#spotlight-category').textContent=d.category;$('#spotlight-title').textContent=d.name;$('#spotlight-description').textContent=d.description;$('#component-tags').innerHTML=d.parts.map(p=>`<span>${p}</span>`).join('');$('#spotlight-tabs').innerHTML=devices.map((x,i)=>`<button aria-pressed="${i===index}" class="${i===index?'selected':''}" data-spotlight="${i}">${x.name}</button>`).join('');$$('[data-spotlight]').forEach(b=>b.onclick=()=>selectSpotlight(+b.dataset.spotlight));}
$('#submit-featured').onclick=()=>{view('sell');const row=$('.device-row');row.querySelector('[data-field="name"]').value=devices[activeDevice].name;row.querySelector('[data-field="category"]').value=devices[activeDevice].category};
$('#eligibility-open').onclick=()=>openInfo('Equipment suitability','<p>Describe medical devices used in monitoring, therapy, diagnostics, emergency care or laboratories. Acceptance depends on the individual equipment, its condition and location.</p><p>Identify ownership or documentation gaps, contamination concerns, patient-data storage and specialist handling requirements. Furniture and other non-device items need a separate review.</p><p>No category or location is automatically approved by this prototype.</p>');
function renderCatalogue(){const query=$('#search').value.trim().toLowerCase(),cat=$('#category').value;const list=devices.filter(d=>(!savedOnly||saved.has(d.id))&&(cat==='all'||d.category===cat)&&(d.name+' '+d.category).toLowerCase().includes(query));$('#cards').innerHTML=list.map(d=>`<article class="device-card"><div class="card-art"><span class="badge">Exploded concept</span><button class="save ${saved.has(d.id)?'on':''}" data-save="${d.id}" aria-label="${saved.has(d.id)?'Unsave':'Save'} ${d.name}" aria-pressed="${saved.has(d.id)}">${saved.has(d.id)?'♥':'♡'}</button><img src="assets/${d.img}" width="1536" height="1024" alt="Exploded 3D illustration of ${d.name}" loading="lazy"></div><div class="card-info"><span class="card-meta">${d.category}</span><h3>${d.name}</h3><p class="location">Illustrative example · Availability by enquiry</p><div class="card-price"><span>Request equipment details</span><button data-detail="${d.id}">Explore ↗</button></div></div></article>`).join('');$('#count').textContent=list.length;$('#saved-count').textContent=saved.size;$('#empty').hidden=list.length>0;$$('[data-save]').forEach(b=>b.onclick=()=>{saved.has(b.dataset.save)?saved.delete(b.dataset.save):saved.add(b.dataset.save);renderCatalogue()});$$('[data-detail]').forEach(b=>b.onclick=()=>deviceDetail(b.dataset.detail));return list.map(({id,name,category})=>({id,name,category}));}
$('#search').oninput=renderCatalogue;$('#category').onchange=renderCatalogue;function stock(only){savedOnly=only;$('#all-stock').classList.toggle('selected',!only);$('#saved-stock').classList.toggle('selected',only);renderCatalogue()}$('#all-stock').onclick=()=>stock(false);$('#saved-stock').onclick=()=>stock(true);$('#reset-filters').onclick=()=>{$('#search').value='';$('#category').value='all';stock(false)};
function deviceDetail(id){const d=devices.find(x=>x.id===id);$('#detail-content').innerHTML=`<p class="eyebrow">DEVICE CATEGORY · ILLUSTRATIVE EXAMPLE</p><div class="detail-grid"><div><img src="assets/${d.img}" alt="Exploded concept of ${d.name}"><p class="micro">Concept render only. Actual unit photos and test documentation are needed for a live equipment offer.</p></div><div><h2>${d.name}</h2><p>${d.description}</p><div class="component-tags">${d.parts.map(x=>`<span>${x}</span>`).join('')}</div><h3>Before buying a refurbished unit</h3><p>Confirm the model, accessories, documented condition, inspection results and applicable warranty or service terms.</p><button class="primary" id="enquire-device">Enquire about this equipment ↗</button></div></div>`;$('#detail-dialog').showModal();$('#enquire-device').onclick=()=>{openInfo('Equipment enquiry',`<p>Tell us what you need from a ${d.name.toLowerCase()}. This example does not represent available stock.</p><form id="buyer-form"><label>Email<input name="email" type="email" required placeholder="you@organisation.com"></label><label class="field-gap">Your requirements<textarea required name="requirements" rows="3" maxlength="2000" placeholder="Model, quantity, budget or required accessories"></textarea></label><button class="primary field-gap">Record demo enquiry</button></form>`);$('#buyer-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);buyerEnquiries.push({device:d.name,email:f.get('email'),requirements:f.get('requirements')});$('#info-dialog').close();toast('Demo buying enquiry recorded in this tab. No message was sent.')}};}
const buyerEnquiries=[];
function addDevice(){if($$('.device-row').length>=20){toast('For more than 20 device types, attach an inventory file.');return}const n=++rowCounter;const row=document.createElement('fieldset');row.className='device-row';row.innerHTML=`<legend>Equipment type ${n}</legend><div class="form-grid"><label>Device type / name<input data-field="name" required maxlength="120" placeholder="e.g. Patient monitor"></label><label>Category<select data-field="category"><option>Patient monitoring</option><option>Infusion therapy</option><option>Laboratory equipment</option><option>Diagnostic imaging</option><option>Emergency care</option><option>Other / unsure</option></select></label><label>Approximate quantity<input data-field="quantity" required type="number" min="1" max="10000" value="1"></label><label>Condition<select data-field="condition"><option>Unknown / not tested</option><option>Working surplus</option><option>Non-working</option><option>Intermittent fault</option><option>Parts only</option></select></label></div><button type="button" class="text-button remove-device">Remove this type</button>`;$('#device-rows').append(row);row.querySelector('.remove-device').onclick=()=>{if($$('.device-row').length===1){toast('Keep at least one equipment type.');return}row.remove()};}
$('#add-device').onclick=addDevice;$('#bulk-start').onclick=()=>{view('sell');if($$('.device-row').length===1)addDevice()};
function filesValid(files,types,max=5){return files.length<=max&&files.every(f=>types.includes(f.type)&&f.size<=10*1024*1024)}
$('#photos').onchange=e=>{const files=[...e.target.files];if(!filesValid(files,['image/jpeg','image/png','image/webp'])){e.target.value='';toast('Choose up to 5 JPG, PNG or WebP files, no larger than 10 MB each.');return}intakePhotos.forEach(a=>URL.revokeObjectURL(a.url));intakePhotos=files.map(f=>({name:f.name,url:URL.createObjectURL(f),file:f,type:'Equipment photo'}));$('#photo-previews').replaceChildren();intakePhotos.forEach(a=>{const img=document.createElement('img');img.src=a.url;img.alt='Preview: '+a.name;$('#photo-previews').append(img)})};
$('#inventory-file').onchange=e=>{const f=e.target.files[0];if(f&&(!/\.(csv|xlsx)$/i.test(f.name)||f.size>10*1024*1024)){e.target.value='';toast('Choose a CSV or XLSX inventory under 10 MB.');return}if(inventoryFile)URL.revokeObjectURL(inventoryFile.url);inventoryFile=f?{name:f.name,file:f,url:URL.createObjectURL(f),type:'Bulk inventory'}:null;$('#inventory-name').textContent=f?'Attached for manual review: '+f.name:''};
$('#sell-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const items=$$('.device-row').map(row=>Object.fromEntries([...row.querySelectorAll('[data-field]')].map(x=>[x.dataset.field,x.dataset.field==='quantity'?Number(x.value):x.value.trim()])));if(items.some(i=>!i.name)||!f.get('organisation').trim()||!f.get('city').trim()){toast('Enter organisation, location and equipment names.');return}const id='MC-'+nextId++;requests.unshift({id,organisation:f.get('organisation').trim(),contact:f.get('contact').trim(),email:f.get('email'),phone:f.get('phone'),city:f.get('city').trim(),intent:f.get('intent'),items,stage:'Submitted',notes:f.get('notes'),technical:{},attachments:[...intakePhotos,...(inventoryFile?[inventoryFile]:[])],history:[{stage:'Submitted',at:new Date().toLocaleString()}],quote:null,collection:'',outcome:'',staff:{technician:'Unassigned',notes:'',acquisition:0,transport:0,parts:0,labour:0,resale:0}});intakePhotos=[];inventoryFile=null;e.target.reset();$('#photo-previews').replaceChildren();$('#inventory-name').textContent='';$('#device-rows').replaceChildren();rowCounter=0;addDevice();view('requests');openRequest(id);toast(id+' created in this demo tab. No enquiry was sent.');};
function totalUnits(r){return r.items.reduce((n,i)=>n+Number(i.quantity),0)}
function rowHtml(r,staff){return `<div class="pipeline-row"><div><h3>${esc(r.items.map(i=>i.name).join(', '))}</h3><p>${r.id} · ${totalUnits(r)} unit(s) · ${esc(r.organisation)}</p></div><p>${esc(r.city)}</p><span class="status">${r.stage}</span><button data-request="${r.id}" data-staff="${staff}">${staff?'Manage':'View request'} →</button></div>`}
function renderRequests(){const open=requests.filter(r=>!['Completed','Declined','Withdrawn'].includes(r.stage));$('#seller-stats').innerHTML=[[open.length,'Open requests'],[requests.filter(r=>r.stage==='Offer ready').length,'Offers to review'],[requests.filter(r=>r.stage==='Collection scheduled').length,'Collections planned'],[requests.reduce((n,r)=>n+totalUnits(r),0),'Equipment units']].map(([n,l])=>`<div><span>${l}</span><strong>${n}</strong></div>`).join('');$('#staff-stats').innerHTML=[[requests.length,'Acquisition requests'],[requests.filter(r=>['Submitted','Suitability review','Assessment'].includes(r.stage)).length,'Awaiting assessment'],[requests.filter(r=>['Inspection','Refurbishment'].includes(r.stage)).length,'In technical review'],[buyerEnquiries.length,'Buying enquiries']].map(([n,l])=>`<div><span>${l}</span><strong>${n}</strong></div>`).join('');$('#request-list').innerHTML=requests.map(r=>rowHtml(r,false)).join('');const filtered=requests.filter(r=>$('#staff-filter').value==='all'||r.stage===$('#staff-filter').value);$('#staff-list').innerHTML=filtered.length?filtered.map(r=>rowHtml(r,true)).join(''):'<div class="empty">No requests at this stage.</div>';if(buyerEnquiries.length)$('#staff-list').innerHTML+='<h3>Buying enquiries</h3>'+buyerEnquiries.map(q=>`<div class="enquiry-record"><strong>${esc(q.device)}</strong><p>${esc(q.email)} · ${esc(q.requirements)}</p></div>`).join('');$$('[data-request]').forEach(b=>b.onclick=()=>b.dataset.staff==='true'?openStaff(b.dataset.request):openRequest(b.dataset.request));}
$('#staff-filter').innerHTML+=[...stages].map(s=>`<option>${s}</option>`).join('');$('#staff-filter').onchange=renderRequests;
function changeStage(r,stage){if(!stages.includes(stage))throw Error('Unknown stage');if(r.stage!==stage){r.stage=stage;r.history.push({stage,at:new Date().toLocaleString()})}}
function attachmentHtml(r){return r.attachments.length?r.attachments.map(a=>`<a class="attachment" href="${a.url}" download="${esc(a.name)}">↧ ${esc(a.name)} <span>${esc(a.type)}</span></a>`).join(''):'<p class="micro">No documents attached. Ownership, service and handover records can be added as they become available.</p>'}
function requestItems(r){return `<div class="item-list">${r.items.map((i,n)=>`<div><strong>${esc(i.name)}</strong><span>Asset ${r.id}-${n+1} · ${i.quantity} unit(s) · ${esc(i.condition)}</span></div>`).join('')}</div>`}
function openRequest(id){const r=requests.find(x=>x.id===id);$('#detail-content').innerHTML=`<p class="eyebrow">MY REQUEST · ${r.id}</p><h2>${esc(r.organisation)}</h2><p>${esc(r.intent)} · ${esc(r.city)} · ${totalUnits(r)} unit(s)</p><span class="status">${r.stage}</span>${requestItems(r)}<div class="timeline">${r.history.map(h=>`<div><b>${h.stage}</b><span>${esc(h.at)}</span></div>`).join('')}</div>${r.quote?`<section class="quote-box"><p class="eyebrow">WRITTEN DEMO OFFER</p><h3>${money(r.quote.amount)}</h3><p>${esc(r.quote.terms)}</p><p>${esc(r.quote.collectionCost)}<br>Offer expiry: ${esc(r.quote.expiry)}</p>${r.stage==='Offer ready'?'<button class="primary" id="accept-quote">Accept demo offer</button>':''}</section>`:''}${r.collection?`<h3>Collection arrangements</h3><p>${esc(r.collection)}</p>`:''}${r.outcome?`<h3>Recorded outcome</h3><p>${esc(r.outcome)}</p>`:''}<details class="request-details"><summary>Add technical details & service history</summary><form id="technical-form"><div class="form-grid field-gap"><label>Manufacturer / model<input name="model" value="${esc(r.technical.model||'')}" maxlength="200"></label><label>Serial numbers / asset references<input name="serial" value="${esc(r.technical.serial||'')}" maxlength="300"></label></div><label>Condition, accessories, history & access needs<textarea name="history" rows="3" maxlength="3000">${esc(r.technical.history||'')}</textarea></label><button class="secondary field-gap">Save demo details</button></form></details><h3>Attachments</h3>${attachmentHtml(r)}<label class="field-gap">Add a document or photo <span class="optional">PDF, image, CSV or XLSX · Max 10 MB</span><input id="request-file" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp,.csv,.xlsx"></label><p class="micro">Attachments stay in this tab. Do not include patient information. No certificate or ownership transfer is issued by this demo.</p>${!['Completed','Withdrawn','Declined'].includes(r.stage)?'<button class="text-button" id="withdraw-request">Withdraw demo request</button>':''}`;$('#detail-dialog').showModal();$('#technical-form').onsubmit=e=>{e.preventDefault();r.technical=Object.fromEntries(new FormData(e.target));toast('Technical details saved for this demo request.')};$('#request-file').onchange=e=>{const f=e.target.files[0];if(!f)return;if(!/\.(pdf|jpe?g|png|webp|csv|xlsx)$/i.test(f.name)||f.size>10*1024*1024){e.target.value='';toast('Choose a supported document under 10 MB.');return}r.attachments.push({name:f.name,url:URL.createObjectURL(f),file:f,type:'Request document'});openRequest(id);toast('Document attached locally to '+id)};if($('#accept-quote'))$('#accept-quote').onclick=()=>{if(r.quote.expiry<new Date().toISOString().slice(0,10)){toast('This sample offer has expired. Request an updated offer.');return}changeStage(r,'Accepted');renderRequests();openRequest(id);toast('Demo offer accepted. No contract or payment was created.')};if($('#withdraw-request'))$('#withdraw-request').onclick=()=>{changeStage(r,'Withdrawn');renderRequests();openRequest(id);toast('Demo request withdrawn.')};}
function openStaff(id){const r=requests.find(x=>x.id===id),s=r.staff;$('#detail-content').innerHTML=`<p class="eyebrow">STAFF DEMO · ${r.id}</p><h2>Assessment & recovery record</h2><p>${esc(r.organisation)} · ${esc(r.contact)} · ${esc(r.email)} · ${esc(r.city)}</p>${requestItems(r)}<details class="request-details"><summary>Submitted information & attachments</summary><p>${esc(r.notes||'No additional notes')}</p><p>Model: ${esc(r.technical.model||'Not provided')}<br>Serial / assets: ${esc(r.technical.serial||'Not provided')}</p><p>${esc(r.technical.history||'')}</p>${attachmentHtml(r)}</details><form id="staff-form"><div class="form-grid field-gap"><label>Current stage<select name="stage">${stages.map(x=>`<option ${x===r.stage?'selected':''}>${x}</option>`).join('')}</select></label><label>Assigned assessor / technician<input name="technician" value="${esc(s.technician)}" maxlength="120"></label></div><label>Inspection findings / repair notes<textarea name="notes" rows="3" maxlength="4000">${esc(s.notes)}</textarea></label><h3>Internal cost estimate <span class="optional">INR</span></h3><div class="cost-grid">${[['acquisition','Acquisition'],['transport','Transport'],['parts','Parts'],['labour','Labour'],['resale','Expected resale']].map(([key,label])=>`<label>${label}<input data-cost name="${key}" type="number" min="0" max="100000000" step="1" value="${s[key]}"></label>`).join('')}</div><div class="margin-box" id="margin-result"></div><h3>Written offer</h3><div class="form-grid"><label>Offer amount (INR)<input name="offerAmount" type="number" min="0" max="100000000" value="${r.quote?.amount??''}"></label><label>Offer expiry<input name="offerExpiry" type="date" value="${r.quote?.expiry??''}"></label></div><label class="field-gap">Offer conditions<textarea name="offerTerms" maxlength="2000" rows="2">${esc(r.quote?.terms??'')}</textarea></label><label class="field-gap">Collection costs / inclusion<input name="collectionCost" maxlength="300" value="${esc(r.quote?.collectionCost??'')}"></label><label class="field-gap">Collection arrangement<textarea name="collection" rows="2" maxlength="1500">${esc(r.collection)}</textarea></label><label class="field-gap">Final disposition / outcome<textarea name="outcome" rows="2" maxlength="1500" placeholder="Record the disposition and reference supporting documents.">${esc(r.outcome)}</textarea></label><div class="form-foot"><p>Internal estimates and notes appear only in this staff demo view. Real access control is not connected.</p><button class="primary">Save demo assessment</button></div></form>`;$('#detail-dialog').showModal();const calc=()=>{const f=new FormData($('#staff-form')),cost=['acquisition','transport','parts','labour'].reduce((n,k)=>n+Number(f.get(k)||0),0),margin=Number(f.get('resale')||0)-cost;$('#margin-result').textContent=`Estimated total cost: ${money(cost)} · Expected contribution: ${money(margin)} (before tax, overheads and other costs)`};$$('[data-cost]').forEach(i=>i.oninput=calc);calc();$('#staff-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),stage=f.get('stage');const hasQuote=String(f.get('offerAmount')).trim()!=='';if((stage==='Offer ready'||hasQuote)&&(!hasQuote||!f.get('offerExpiry')||!String(f.get('offerTerms')).trim()||!String(f.get('collectionCost')).trim())){toast('Complete the offer amount, expiry, conditions and collection costs.');return}if(stage==='Collection scheduled'&&!String(f.get('collection')).trim()){toast('Add collection arrangements before marking it scheduled.');return}if(stage==='Completed'&&!String(f.get('outcome')).trim()){toast('Record the final disposition before completing this request.');return}r.staff={technician:f.get('technician'),notes:f.get('notes'),...Object.fromEntries(['acquisition','transport','parts','labour','resale'].map(k=>[k,Number(f.get(k))]))};r.quote=hasQuote?{amount:Number(f.get('offerAmount')),expiry:f.get('offerExpiry'),terms:f.get('offerTerms'),collectionCost:f.get('collectionCost')}:null;r.collection=f.get('collection');r.outcome=f.get('outcome');changeStage(r,stage);renderRequests();$('#detail-dialog').close();toast('Demo assessment updated. Seller tracking now reflects its status.')};}
$('#about').onclick=()=>openInfo('About this prototype','<p>Medicycle is a working-name concept for equipment acquisition, assessment and recovery. It is not affiliated with the Australian business used as inspiration.</p><p>This version uses fictional examples and in-memory records. It has no authentication, shared database, live stock, messaging, payments or collection booking.</p><p>Device images are illustrative exploded 3D renders. They are not interactive CAD models, service instructions or proof of equipment condition. Supabase integration and production permissions remain a separate phase.</p>');
addDevice();selectSpotlight(0);renderCatalogue();renderRequests();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'search_demo_equipment',title:'Search sample device categories',description:'Filter the visible illustrative equipment catalogue. Does not search live stock.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},execute:input=>{if(!input||typeof input.query!=='string'||input.query.length>200)throw Error('query must be at most 200 characters');view('market');savedOnly=false;$('#search').value=input.query;$('#category').value='all';stock(false);return{devices:renderCatalogue()}}},{name:'start_demo_equipment_assessment',title:'Open seller enquiry',description:'Open the initial seller enquiry form without submitting anything.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:input=>{if(!input||Object.keys(input).length)throw Error('No arguments expected');return{view:view('sell'),submitted:false}}}];for(const t of tools){try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}}}
